/* Le Pot Magique 2.0 — application 100 % statique, sans serveur.
 * Données personnelles : conservées dans le navigateur, jamais envoyées par le site.
 * Une nouvelle classe démarre vide ; les classes déjà enregistrées sont conservées.
 */
'use strict';
const VISUALS=[{id:'sticks',name:'Bâtonnets',emoji:'🪵'},{id:'pencils',name:'Crayons',emoji:'✏️'},{id:'wheel',name:'Roue',emoji:'🎡'},{id:'cards',name:'Cartes',emoji:'🃏'},{id:'balls',name:'Boules',emoji:'🎱'}];
const AVATAR_COLORS=['#e8f0df','#f2e8f8','#ffecdf','#f8e9ef','#e0edf7'];
const PASTEL_COLORS=['#b6d7bc','#dac8ef','#f5cdb5','#f4d8e4','#f3dfab','#c6dce9','#d3e8c6','#e8d4bf'];
const HELP={
  random:{title:'Tirage 100 % aléatoire',body:'Chaque élève présent qui n’a pas encore été tiré pendant le tour en cours possède exactement la même probabilité d’être sélectionné. Les interrogations passées ne changent pas cette probabilité. Avec 20 élèves éligibles, chacun a 5 % de chances.'},
  fair:{title:'Tirage équitable',body:'Le hasard reste présent, mais les chances sont pondérées selon le nombre d’interrogations confirmées par jour de présence lors des 20 derniers jours de classe enregistrés. Plus ce taux est faible, plus la probabilité est élevée. Les élèves absents et ceux déjà tirés dans le tour restent exclus. La formule utilisée est poids = 1 ÷ (0,5 + interrogations ÷ jours de présence) ; la probabilité est le poids de l’élève divisé par la somme des poids des élèves éligibles.'},
  times:{title:'Nombre d’interrogations',body:'Nombre de réponses orales réellement confirmées pour cet élève ou cette période. Un tirage annulé ne compte jamais.'},
  share:{title:'Part des interrogations',body:'Pourcentage des interrogations de la classe attribuées à un élève : nombre de ses interrogations ÷ total des interrogations confirmées × 100. Ce n’est pas sa probabilité d’être tiré.'},
  presenceRate:{title:'Interrogations par jour de présence',body:'Nombre d’interrogations confirmées ÷ nombre de journées où l’élève était marqué présent. Les journées ne sont comptées que si la présence a été enregistrée dans l’application ; cela évite de supposer qu’un élève est présent tous les jours.'},
  coverage:{title:'Couverture de la classe',body:'Pourcentage d’élèves présents au moins une fois pendant la période qui ont été interrogés au moins une fois. Un élève interrogé trois fois compte une seule fois pour cet indicateur.'},
  eligible:{title:'Élèves éligibles',body:'Ce sont les élèves présents qui ne sont pas encore passés pendant le tour actuel. Un nouveau tour remet tous les bâtonnets en jeu sans effacer les statistiques.'},
  probability:{title:'Probabilité du prochain tirage',body:'Pourcentage de chances de sortir au prochain tirage seulement. En mode aléatoire, tous les élèves éligibles ont la même chance. En mode équitable, les poids sont ajustés par les participations et les jours de présence enregistrés.'},
  attendance:{title:'Présences prises en compte',body:'La première utilisation du tirage ou une modification des absences enregistre la présence de la classe pour cette date. Un jour où le site n’est pas utilisé n’est pas supposé être un jour de présence. Vous pouvez corriger les présences depuis l’historique.'},
  equity:{title:'Écart de participation',body:'Compare le nombre d’interrogations par jour de présence, et pas seulement le nombre total d’interrogations. Cet outil sert à repérer d’éventuels écarts, sans juger les élèves ni garantir un nombre identique de prises de parole.'},
  subject:{title:'Matières',body:'La matière sélectionnée est enregistrée avec chaque interrogation. Vous pourrez ensuite filtrer les statistiques par français, mathématiques, histoire ou toute autre matière que vous ajouterez.'},
  stored:{title:'Vos données restent sur cet appareil',body:'GitHub Pages affiche le site, mais n’héberge pas votre suivi. Les données sont conservées localement dans ce navigateur. Pour changer d’ordinateur ou éviter une perte si Chrome est réinitialisé, exportez régulièrement une sauvegarde JSON.'}
};
const $=(sel,root=document)=>root.querySelector(sel);
const $$=(sel,root=document)=>Array.from(root.querySelectorAll(sel));
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ic=(id,cls='')=>`<svg aria-hidden="true" class="icon ${cls}"><use href="#i-${id}"></use></svg>`;
const help=(key)=>`<button class="help-dot" type="button" data-action="help" data-key="${esc(key)}" title="Comprendre cet indicateur" aria-label="Comprendre : ${esc(HELP[key]?.title||key)}">?</button>`;
const uid=()=>typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():'id'+Date.now().toString(36)+Math.random().toString(36).slice(2,10);
const isoDay=(date=new Date())=>{const d=new Date(date);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const dateObj=s=>new Date(`${s}T12:00:00`);
const fmtDate=(s,opts={weekday:'long',day:'numeric',month:'long'})=>dateObj(s).toLocaleDateString('fr-FR',opts);
const fmtInt=n=>Number(n||0).toLocaleString('fr-FR');
const fmtPct=n=>`${(n||0).toLocaleString('fr-FR',{maximumFractionDigits:1})} %`;
const fmtRate=n=>(n||0).toLocaleString('fr-FR',{maximumFractionDigits:2});
const startOfWeek=s=>{const d=dateObj(s);d.setDate(d.getDate()-((d.getDay()+6)%7));return isoDay(d)};
const schoolYearLabel=()=>{const d=new Date(),start=d.getMonth()>=7?d.getFullYear():d.getFullYear()-1;return `${start}-${start+1}`};
const clone=value=>JSON.parse(JSON.stringify(value));
const initialLayout=()=>({id:uid(),name:'Ma disposition',items:[
  {id:uid(),type:'board',x:30,y:3,rotation:0,studentIds:[]},
  {id:uid(),type:'desk2',x:17,y:23,rotation:0,studentIds:[null,null]},
  {id:uid(),type:'desk2',x:58,y:23,rotation:0,studentIds:[null,null]},
  {id:uid(),type:'desk2',x:17,y:47,rotation:0,studentIds:[null,null]},
  {id:uid(),type:'desk2',x:58,y:47,rotation:0,studentIds:[null,null]},
  {id:uid(),type:'desk2',x:17,y:72,rotation:0,studentIds:[null,null]},
  {id:uid(),type:'desk2',x:58,y:72,rotation:0,studentIds:[null,null]},
  {id:uid(),type:'teacher',x:80,y:5,rotation:0,studentIds:[]},
  {id:uid(),type:'window',x:1,y:37,rotation:90,studentIds:[]},
  {id:uid(),type:'door',x:92,y:85,rotation:0,studentIds:[]}
]});
function makeYear(label,seed=[]){const layout=initialLayout();return {id:uid(),label,createdAt:new Date().toISOString(),students:seed.map(s=>typeof s==='string'?{id:uid(),name:s,active:true,addedOn:isoDay()}:{id:s.id||uid(),name:s.name,active:true,addedOn:isoDay()}),attendance:{},events:[],observations:[],questions:[],layouts:[layout],activeLayoutId:layout.id,round:[],classDays:[]};}
const makeState=()=>{const y=makeYear(schoolYearLabel());return {version:2,activeYearId:y.id,years:[y],preferences:{confetti:true,reducedMotion:false},visual:'sticks',mode:'random',subject:'',askQuestion:false};};
let S=null;
const UI={page:'tirage',statsPeriod:'week',statsFrom:isoDay(),statsTo:isoDay(),statsSubject:'',studentFilter:'',selectedStudentId:'',calendarMonth:isoDay().slice(0,7)+'-01',calendarSelected:isoDay(),selectedLayoutItemId:'',pending:null,lastResult:null,animating:false,projector:false,toastTimer:null,importing:false};
const yr=()=>S.years.find(y=>y.id===S.activeYearId)||S.years[0];
const studentById=id=>yr().students.find(s=>s.id===id);
const activeStudents=()=>yr().students.filter(s=>s.active);
const today=()=>isoDay();
const todayAttendance=()=>yr().attendance[today()]||{};
const isAbsent=(id,date=today())=>yr().attendance[date]?.[id]==='absent';
const hasConfirmed=id=>yr().events.some(e=>e.studentId===id);
const getEligible=()=>activeStudents().filter(s=>!isAbsent(s.id)&&!yr().round.includes(s.id));
const getLayout=()=>yr().layouts.find(l=>l.id===yr().activeLayoutId)||yr().layouts[0];
const subjects=()=>[...new Set(['Sans matière','Français','Mathématiques','Histoire','Géographie','Sciences','Anglais','Lecture',...yr().questions.map(q=>q.subject),...yr().events.map(e=>e.subject).filter(Boolean)])];
const subjectOptions=(chosen='',includeAll=false)=>`${includeAll?'<option value="">Toutes les matières</option>':''}${subjects().map(s=>`<option value="${esc(s)}" ${s===chosen?'selected':''}>${esc(s)}</option>`).join('')}`;
const rand=()=>{if(typeof crypto!=='undefined'&&crypto.getRandomValues){const v=new Uint32Array(1);crypto.getRandomValues(v);return v[0]/4294967296}return Math.random()};
const pickUniform=arr=>arr[Math.floor(rand()*arr.length)];
const pastelFor=i=>PASTEL_COLORS[i%PASTEL_COLORS.length];
const avatarColor=i=>AVATAR_COLORS[i%AVATAR_COLORS.length];
const ensureAttendanceDay=(date=today())=>{const y=yr();if(!y.attendance[date]){y.attendance[date]={};y.students.filter(s=>s.active).forEach(s=>y.attendance[date][s.id]='present');}if(!y.classDays.includes(date))y.classDays.push(date);};
const rateWindowDays=()=>yr().classDays.filter(d=>d<=today()).sort().slice(-20);
function equityData(candidates=getEligible()){
  const days=rateWindowDays();
  const counts=new Map();const presence=new Map();
  candidates.forEach(s=>{counts.set(s.id,yr().events.filter(e=>e.studentId===s.id&&days.includes(eventDay(e))).length);presence.set(s.id,days.filter(d=>yr().attendance[d]?.[s.id]==='present').length)});
  const weights=candidates.map(s=>{const p=Math.max(1,presence.get(s.id));const perDay=counts.get(s.id)/p;return {id:s.id,person:s,count:counts.get(s.id),presentDays:presence.get(s.id),rate:perDay,weight:1/(.5+perDay)}});
  const total=weights.reduce((sum,r)=>sum+r.weight,0);
  return weights.map(r=>({...r,probability:total?100*r.weight/total:0}));
}
function pickCandidate(){const eligible=getEligible();if(!eligible.length)return null;if(S.mode==='random')return pickUniform(eligible);const weights=equityData(eligible);const draw=rand()*weights.reduce((sum,r)=>sum+r.weight,0);let cumulative=0;for(const entry of weights){cumulative+=entry.weight;if(draw<cumulative)return entry.person;}return weights.at(-1).person;}
/* Sauvegarde séquentielle pour ne jamais écraser une modification plus récente. */
let dbPromise=null,writeQueue=Promise.resolve(),backend='IndexedDB';
function openDB(){if(!('indexedDB'in window))return Promise.reject(new Error('IndexedDB indisponible'));if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const request=indexedDB.open('le-pot-magique',1);request.onupgradeneeded=()=>request.result.createObjectStore('app');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});return dbPromise;}
async function readState(){try{const db=await openDB();return await new Promise((resolve,reject)=>{const req=db.transaction('app','readonly').objectStore('app').get('state');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}catch(err){backend='localStorage';try{return JSON.parse(localStorage.getItem('le-pot-magique-v2')||'null')}catch(e){return null}}}
async function writeState(snapshot){if(backend==='localStorage'){localStorage.setItem('le-pot-magique-v2',JSON.stringify(snapshot));return;}try{const db=await openDB();await new Promise((resolve,reject)=>{const tx=db.transaction('app','readwrite');tx.objectStore('app').put(snapshot,'state');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}catch(err){backend='localStorage';localStorage.setItem('le-pot-magique-v2',JSON.stringify(snapshot));}}
function save(){const snapshot=clone(S);writeQueue=writeQueue.catch(()=>{}).then(()=>writeState(snapshot)).then(()=>{const el=$('#saveStatus');if(el)el.textContent='Données enregistrées sur cet appareil';}).catch(e=>{console.error('Erreur de sauvegarde',e);const el=$('#saveStatus');if(el)el.textContent='Attention : sauvegarde impossible. Exportez vos données.';toast('Sauvegarde impossible : vérifiez l’espace disponible.','error');});return writeQueue;}
function migrateLegacy(){try{const old=JSON.parse(localStorage.getItem('classe_batonnets')||'null');if(!Array.isArray(old)||!old.length||!old.every(x=>x&&typeof x.name==='string'))return null;const state=makeState();const y=yrFor(state);y.students=old.map(s=>({id:uid(),name:String(s.name).slice(0,100),active:true,addedOn:today()}));y.round=y.students.filter((s,i)=>old[i]?.picked).map(s=>s.id);ensureMigrationNote();return state;}catch(e){return null}}
const yrFor=state=>state.years[0];
function ensureMigrationNote(){try{sessionStorage.setItem('pot-magique-migrated','1')}catch(e){}}
function normalizeState(state){if(!state||state.version!==2||!Array.isArray(state.years)||!state.years.length)throw new Error('Format de sauvegarde incompatible');for(const y of state.years){if(!Array.isArray(y.students)||!Array.isArray(y.events)||!y.attendance||!Array.isArray(y.layouts))throw new Error('Sauvegarde incomplète');y.round=Array.isArray(y.round)?y.round:[];y.classDays=Array.isArray(y.classDays)?y.classDays:Object.keys(y.attendance);y.questions=Array.isArray(y.questions)?y.questions:[];y.observations=Array.isArray(y.observations)?y.observations:[];if(!y.layouts.length){const l=initialLayout();y.layouts=[l];y.activeLayoutId=l.id;}if(!y.layouts.some(l=>l.id===y.activeLayoutId))y.activeLayoutId=y.layouts[0].id;}
 state.activeYearId=state.years.some(y=>y.id===state.activeYearId)?state.activeYearId:state.years[0].id;state.preferences={confetti:true,reducedMotion:false,...state.preferences};if(!VISUALS.some(v=>v.id===state.visual))state.visual='sticks';if(!['random','fair'].includes(state.mode))state.mode='random';state.subject=typeof state.subject==='string'?state.subject:'';state.askQuestion=!!state.askQuestion;return state;}
function toast(message,type='success'){const root=$('#toastRoot');if(!root)return;root.innerHTML=`<div class="toast ${type==='error'?'error':''}" role="status">${esc(message)}</div>`;clearTimeout(UI.toastTimer);UI.toastTimer=setTimeout(()=>root.innerHTML='',3400)}
function modal(title,body,actions=''){const root=$('#modalRoot');root.innerHTML=`<div class="modal-backdrop" data-action="modal-backdrop"><section class="modal-panel" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-top"><h2>${esc(title)}</h2><button class="modal-close" data-action="close-modal" aria-label="Fermer">${ic('close')}</button></div><div>${body}</div>${actions}</section></div>`;$('.modal-close',root)?.focus()}
function closeModal(){$('#modalRoot').innerHTML=''}
function confirmDialog(title,body,yes,opts={}){modal(title,`<p>${esc(body)}</p>`,`<div class="modal-actions"><button class="btn btn-outline" data-action="close-modal">Annuler</button><button class="btn ${opts.danger?'btn-danger':'btn-primary'}" id="modalConfirm">${esc(opts.label||'Confirmer')}</button></div>`);$('#modalConfirm').addEventListener('click',()=>{closeModal();yes()},{once:true});}
function downloadBlob(name,contents,type){const blob=new Blob([contents],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportJSON(){downloadBlob(`pot-magique-sauvegarde-${today()}.json`,JSON.stringify(S,null,2),'application/json;charset=utf-8');toast('Sauvegarde JSON téléchargée.');}
function exportCSV(){const y=yr(),header=['Date','Heure','Élève','Matière','Mode','Animation','Question'],rows=y.events.slice().sort((a,b)=>a.at.localeCompare(b.at)).map(e=>[e.at.slice(0,10),new Date(e.at).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'}),y.students.find(s=>s.id===e.studentId)?.name||'Élève archivé',e.subject||'Sans matière',e.mode==='fair'?'Équitable':'Aléatoire',VISUALS.find(v=>v.id===e.visual)?.name||e.visual,e.questionText||'']);const csv=[header,...rows].map(row=>row.map(v=>{const text=String(v??'');const safe=/^[=+@\-\t\r]/.test(text)?"'"+text:text;return '"'+safe.replaceAll('"','""')+'"'}).join(';')).join('\r\n');downloadBlob(`pot-magique-${y.label}-interrogations.csv`,'\ufeff'+csv,'text/csv;charset=utf-8');toast('Historique CSV téléchargé.');}
function exportStatsCSV(){const stats=getStats(),bounds=periodBounds(),y=yr();const csvRow=values=>values.map(value=>{const original=String(value??'');const safe=/^[=+@\-\t\r]/.test(original)?"'"+original:original;return '"'+safe.replaceAll('"','""')+'"'}).join(';');const header=['Élève','Interrogations','Part des interrogations (%)','Jours de présence enregistrés','Interrogations par jour présent','Début','Fin','Matière'];const rows=y.students.filter(s=>s.active||stats.counts.get(s.id)||stats.presence.get(s.id)).sort((a,b)=>a.name.localeCompare(b.name,'fr')).map(student=>{const count=stats.counts.get(student.id)||0,present=stats.presence.get(student.id)||0;return [student.name,count,stats.total?(100*count/stats.total).toFixed(2):0,present,present?(count/present).toFixed(2):0,bounds.start,bounds.end,UI.statsSubject||'Toutes']});rows.push([]);rows.push(['TOTAL CLASSE',stats.total,stats.total?100:0,'','','','','']);rows.push(['ÉLÈVES DIFFÉRENTS',stats.uniqueStudents.size]);rows.push(['COUVERTURE CLASSE (%)',stats.coverage.toFixed(2)]);downloadBlob(`pot-magique-${y.label}-statistiques-${UI.statsPeriod}.csv`,'\ufeff'+[header,...rows].map(csvRow).join('\r\n'),'text/csv;charset=utf-8');toast('Statistiques CSV téléchargées, prêtes pour Excel.');}
const pageName={tirage:'Tirage au sort',stats:'Statistiques',students:'Mes élèves',layout:'Plan de classe',history:'Historique',questions:'Mes questions',settings:'Paramètres'};
function renderChrome(){const select=$('#globalYearSelect');if(select)select.innerHTML=S.years.map(y=>`<option value="${esc(y.id)}" ${y.id===S.activeYearId?'selected':''}>${esc(y.label)}</option>`).join('');$('#todayLabel').textContent=new Date().toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'});$$('[data-page].nav-item').forEach(e=>{e.classList.toggle('active',e.dataset.page===UI.page);e.setAttribute('aria-current',e.dataset.page===UI.page?'page':'false')})}
function pageHeading(eyebrow,title,subtitle,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${title}</h1><p class="page-subtitle">${subtitle}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`}
function render(){renderChrome();const pages={tirage:renderDraw,stats:renderStats,students:renderStudents,layout:renderLayout,history:renderHistory,questions:renderQuestions,settings:renderSettings};$('#pageContent').innerHTML=(pages[UI.page]||renderDraw)();if(UI.page==='tirage'&&S.visual==='wheel')paintWheel();if(UI.page==='tirage'&&UI.pending&&!UI.animating)showReveal();if(UI.page==='layout')setupBoardDnD();renderProjector();}
function goPage(name){if(UI.animating){toast('Terminez d’abord le tirage en cours.');return;}if(UI.pending){toast('Confirmez ou annulez le tirage avant de changer de page.');return;}UI.page=name;closeModal();$('#sidebar').classList.remove('open');$('.mobile-dim')?.remove();render();$('#pageContent').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function changeYear(id){if(!S.years.some(y=>y.id===id))return;if(UI.pending||UI.animating){toast('Terminez le tirage en cours.');renderChrome();return;}S.activeYearId=id;UI.selectedStudentId='';UI.selectedLayoutItemId='';UI.lastResult=null;UI.calendarSelected=today();UI.calendarMonth=today().slice(0,7)+'-01';save();render();}
